#!/usr/bin/env bash
# Acadia-Client — per-repo validation gate (stack: cmake).
# Generated by tools/validate/generate.sh. Edit freely afterwards.
#
#   quick   seconds. Repo shape, no build.
#   full    minutes. Configure + build + ctest + lint.
#
# Client runs on the RPi 5/CM4/CM5 and links Acadia-HAL via add_subdirectory.
# It must NEVER regenerate protos (C++ ODR constraint) — generation belongs to
# HAL. Links break loudly if this rule is violated, which the gate checks.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "CMakeLists present" 'test -f CMakeLists.txt'
assert "sibling Acadia-HAL checkout present" \
  'test -d ../Acadia-HAL || { echo "missing sibling Acadia-HAL checkout"; exit 1; }'

# Client links HAL's canonical protos. The proto sources it compiles must exist
# in the sibling HAL checkout; if they drift, the build fails loudly here.
assert "referenced HAL proto sources exist" \
  'for p in common client_service hal_service; do
     [ -f ../Acadia-HAL/protos/$p.proto ] || { echo "missing $p.proto in Acadia-HAL"; exit 1; }
   done'

# Task 80: every registry module must have a HAL proto + Client adapter
# (generated-proto consumption contract).
check "HAL-to-Client proto contract" "bash" 'bash tools/proto_contract_test.sh'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "configure" "cmake ninja" 'make configure'
check "build" "cmake ninja g++" 'make build'
check "tests (ctest)" "cmake" 'make test'
check "lint" "cppcheck clang-format" 'make lint'

report "$TIER"
